use vstd::prelude::*;

verus! {
    // Returns the minimum element of a non‐empty vector of i8s.
    // Postcondition: the result is ≤ every element of the vector,
    //                and equal to some element of the vector.
    fn min(a: Vec<i8>) -> i8
        requires
            a.len() > 0,
        ensures
            // result is less than or equal to every element
            forall(|j: usize| j < a.len() ==> result <= a[j]),
            // result equals one of the elements
            exists(|j: usize| j < a.len() && result == a[j]),
    {
        let mut i: usize = 1;
        // initialize cur to the first element; since len>0 this is safe
        let mut cur: i8 = a.get(0);
        let n = a.len();

        // We scan the array from index 1 up to n, maintaining:
        //  1. i ≤ n
        //  2. cur ≤ a[j]  for all j < i
        //  3. there is some j < i with cur == a[j]
        while i < n
            invariant
                i <= n,
                forall(|j: usize| j < i ==> cur <= a[j]),
                exists(|j: usize| j < i && cur == a[j]),
            decreases
                n - i,
        {
            let v = a.get(i);
            if v < cur {
                cur = v;
            }
            i += 1;
        }

        // when i == n, by the invariants cur <= every a[j] for j<n (= len),
        // and cur == a[j] for some j<n.  That gives exactly our ensures.
        cur
    }
}

fn main() {
    // some quick runtime checks (not part of the proof)
    let v1 = vec![3i8, 1, 4, -2, 5];
    assert!(min(v1.clone()) == -2);
    let v2 = vec![7];
    assert!(min(v2.clone()) == 7);
}